#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, k, a[1001];
    scanf("%d%d", &n, &k);
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);
    long long sum = 0, best = -1;
    int start = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
        if (i >= k)
            sum -= a[i - k];
        if (i >= k - 1 && sum > best) {
            best = sum;
            start = i - k + 1;
        }
    }
    printf("%lld %d\n", best, start);
    return 0;
}

