#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, m, g[80][80] = {0};
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u][v] = 1;
    }
    int d[80], q[80], head = 0, tail = 0;
    long long ways[80] = {0};
    for (int i = 0; i < n; i++)
        d[i] = -1;
    d[0] = 0;
    ways[0] = 1;
    q[tail++] = 0;
    while (head < tail) {
        int u = q[head++];
        for (int v = 0; v < n; v++)
            if (g[u][v]) {
                if (d[v] < 0) {
                    d[v] = d[u] + 1;
                    q[tail++] = v;
                }
                if (d[v] == d[u] + 1)
                    ways[v] = (ways[v] + ways[u]) % 1000000007;
            }
    }
    printf("%d %lld\n", d[n - 1], ways[n - 1]);
    return 0;
}

