#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int l, r, v;
} Job;
int cmp_job(const void *p, const void *q) {
    const Job *a = p, *b = q;
    return (a->r > b->r) - (a->r < b->r);
}
int main(void) {
    int n;
    Job a[300];
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d%d%d", &a[i].l, &a[i].r, &a[i].v);
    qsort(a, (size_t)n, sizeof *a, cmp_job);
    long long dp[301] = {0};
    for (int i = 0; i < n; i++) {
        int lo = 0, hi = i;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid].r <= a[i].l)
                lo = mid + 1;
            else
                hi = mid;
        }
        long long take = dp[lo] + a[i].v;
        dp[i + 1] = dp[i] > take ? dp[i] : take;
    }
    printf("%lld\n", dp[n]);
    return 0;
}

