#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id, p, g, c;
} Team;
int cmp_team(const void *p, const void *q) {
    const Team *a = p, *b = q;
    if (a->p != b->p)
        return (a->p < b->p) - (a->p > b->p);
    int da = a->g - a->c, db = b->g - b->c;
    if (da != db)
        return (da < db) - (da > db);
    if (a->g != b->g)
        return (a->g < b->g) - (a->g > b->g);
    return (a->id > b->id) - (a->id < b->id);
}
int main(void) {
    int n;
    Team a[500];
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d%d%d%d", &a[i].id, &a[i].p, &a[i].g, &a[i].c);
    qsort(a, (size_t)n, sizeof *a, cmp_team);
    if (!n)
        puts("EMPTY");
    for (int i = 0; i < n; i++)
        printf("%s%d", i ? " " : "", a[i].id);
    if (n)
        puts("");
    return 0;
}

