#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp_int(const void *p, const void *q) {
    int a = *(const int *)p, b = *(const int *)q;
    return (a > b) - (a < b);
}

int main(void) {
    int n, k, a[1001];
    scanf("%d%d", &n, &k);
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);
    qsort(a, (size_t)n, sizeof *a, cmp_int);
    int l = 0, r = n - 1, trips = 0;
    while (l <= r) {
        if (l < r && a[l] + a[r] <= k)
            l++;
        r--;
        trips++;
    }
    printf("%d\n", trips);
    return 0;
}

