#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int players, positions, edge_count, g[12][12], owner[12], seen[12];
int augment(int u) {
    for (int v = 0; v < positions; v++)
        if (g[u][v] && !seen[v]) {
            seen[v] = 1;
            if (owner[v] < 0 || augment(owner[v])) {
                owner[v] = u;
                return 1;
            }
        }
    return 0;
}
int main(void) {
    scanf("%d%d%d", &players, &positions, &edge_count);
    for (int i = 0; i < edge_count; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u][v] = 1;
    }
    for (int v = 0; v < positions; v++)
        owner[v] = -1;
    int answer = 0;
    for (int u = 0; u < players; u++) {
        memset(seen, 0, sizeof seen);
        answer += augment(u);
    }
    printf("%d\n", answer);
    return 0;
}

