#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int vertices, edges_count, g[80][80], discovery[80], low[80], cut[80], clock_id;
void dfs_cut(int u, int parent) {
    discovery[u] = low[u] = ++clock_id;
    int children = 0;
    for (int v = 0; v < vertices; v++)
        if (g[u][v]) {
            if (!discovery[v]) {
                children++;
                dfs_cut(v, u);
                if (low[v] < low[u])
                    low[u] = low[v];
                if (parent >= 0 && low[v] >= discovery[u])
                    cut[u] = 1;
            } else if (v != parent && discovery[v] < low[u])
                low[u] = discovery[v];
        }
    if (parent < 0 && children > 1)
        cut[u] = 1;
}
int main(void) {
    scanf("%d%d", &vertices, &edges_count);
    for (int i = 0; i < edges_count; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u][v] = g[v][u] = 1;
    }
    for (int u = 0; u < vertices; u++)
        if (!discovery[u])
            dfs_cut(u, -1);
    int first = 1;
    for (int u = 0; u < vertices; u++)
        if (cut[u]) {
            printf("%s%d", first ? "" : " ", u);
            first = 0;
        }
    if (first)
        printf("EMPTY");
    puts("");
    return 0;
}

