#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int l, r;
} Slot;
int cmp_slot(const void *p, const void *q) {
    const Slot *a = p, *b = q;
    return (a->l > b->l) - (a->l < b->l);
}
int heap[1000], heap_size;
void push_end(int x) {
    int i = heap_size++;
    while (i && heap[(i - 1) / 2] > x) {
        heap[i] = heap[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    heap[i] = x;
}
void pop_end(void) {
    int x = heap[--heap_size], i = 0;
    while (i * 2 + 1 < heap_size) {
        int j = i * 2 + 1;
        if (j + 1 < heap_size && heap[j + 1] < heap[j])
            j++;
        if (heap[j] >= x)
            break;
        heap[i] = heap[j];
        i = j;
    }
    if (heap_size)
        heap[i] = x;
}
int main(void) {
    int n;
    Slot a[1000];
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d%d", &a[i].l, &a[i].r);
    qsort(a, (size_t)n, sizeof *a, cmp_slot);
    int answer = 0;
    for (int i = 0; i < n; i++) {
        while (heap_size && heap[0] <= a[i].l)
            pop_end();
        push_end(a[i].r);
        if (heap_size > answer)
            answer = heap_size;
    }
    printf("%d\n", answer);
    return 0;
}

