#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int u, v, w;
} Edge;
int parent[80], size[80];
int root(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
int cmp_edge(const void *p, const void *q) {
    const Edge *a = p, *b = q;
    return (a->w > b->w) - (a->w < b->w);
}
int main(void) {
    int n, m;
    Edge a[3160];
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++)
        scanf("%d%d%d", &a[i].u, &a[i].v, &a[i].w);
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    qsort(a, (size_t)m, sizeof *a, cmp_edge);
    long long total = 0;
    int chosen = 0;
    for (int i = 0; i < m; i++) {
        int x = root(a[i].u), y = root(a[i].v);
        if (x != y) {
            if (size[x] < size[y]) {
                int t = x;
                x = y;
                y = t;
            }
            parent[y] = x;
            size[x] += size[y];
            total += a[i].w;
            chosen++;
        }
    }
    printf("%lld\n", chosen == n - 1 ? total : -1);
    return 0;
}

