#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int h[1000], hsize;
void insert(int x) {
    int i = hsize++;
    while (i && h[(i - 1) / 2] > x) {
        h[i] = h[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    h[i] = x;
}
void replace_min(int x) {
    int i = 0;
    while (i * 2 + 1 < hsize) {
        int j = i * 2 + 1;
        if (j + 1 < hsize && h[j + 1] < h[j])
            j++;
        if (h[j] >= x)
            break;
        h[i] = h[j];
        i = j;
    }
    h[i] = x;
}
int main(void) {
    int n, k;
    scanf("%d%d", &n, &k);
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (hsize < k) {
            insert(x);
            sum += x;
        } else if (x > h[0]) {
            sum += x - h[0];
            replace_min(x);
        }
        printf("%s%lld", i ? " " : "", sum);
    }
    if (!n)
        printf("EMPTY");
    puts("");
    return 0;
}

