#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    int g[60][60] = {0};
    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d%d%d", &u, &v, &w);
        g[u][v] = g[v][u] = w;
    }
    long long d[120];
    int used[120] = {0};
    for (int i = 0; i < 2 * n; i++)
        d[i] = 1000000000000LL;
    d[0] = 0;
    for (int step = 0; step < 2 * n; step++) {
        int u = -1;
        for (int i = 0; i < 2 * n; i++)
            if (!used[i] && (u < 0 || d[i] < d[u]))
                u = i;
        if (u < 0 || d[u] == 1000000000000LL)
            break;
        used[u] = 1;
        int city = u % n, spent = u / n;
        for (int v = 0; v < n; v++)
            if (g[city][v]) {
                int next = spent * n + v;
                if (d[u] + g[city][v] < d[next])
                    d[next] = d[u] + g[city][v];
                if (!spent && d[u] < d[n + v])
                    d[n + v] = d[u];
            }
    }
    long long ans = d[n - 1] < d[2 * n - 1] ? d[n - 1] : d[2 * n - 1];
    printf("%lld\n", ans == 1000000000000LL ? -1 : ans);
    return 0;
}

