int values[2000], buffer[2000];
long long sort_count(int lo, int hi) {
    if (hi - lo <= 1)
        return 0;
    int mid = lo + (hi - lo) / 2;
    long long ans = sort_count(lo, mid) + sort_count(mid, hi);
    int i = lo, j = mid, w = lo;
    while (i < mid || j < hi) {
        if (j == hi || (i < mid && values[i] <= values[j]))
            buffer[w++] = values[i++];
