int length;
long long bit[1001];
void add_value(int i, int delta) {
    for (; i <= length; i += i & -i)
        bit[i] += delta;
}
long long prefix(int i) {
    long long s = 0;
    for (; i > 0; i -= i & -i)
        s += bit[i];
    return s;
}
int main(void) {
