#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long long a[8][8];
} Matrix;
Matrix multiply(Matrix x, Matrix y, int n) {
    Matrix z = {{{0}}};
    for (int i = 0; i < n; i++)
        for (int k = 0; k < n; k++)
            for (int j = 0; j < n; j++)
                z.a[i][j] = (z.a[i][j] + x.a[i][k] * y.a[k][j]) % 1000000007;
    return z;
}
int main(void) {
    int n, m;
    long long k;
    scanf("%d%d%lld", &n, &m, &k);
    Matrix base = {{{0}}}, result = {{{0}}};
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        base.a[u][v] = 1;
    }
    for (int i = 0; i < n; i++)
        result.a[i][i] = 1;
    while (k) {
        if (k & 1)
            result = multiply(result, base, n);
        base = multiply(base, base, n);
        k /= 2;
    }
    printf("%lld\n", result.a[0][n - 1]);
    return 0;
}

