    int best = a[0] + a[1] + a[2];
    for (int i = 0; i < n - 2; i++) {
        int l = i + 1, r = n - 1;
        while (l < r) {
            int sum = a[i] + a[l] + a[r];
            if (abs(sum - k) < abs(best - k) || (abs(sum - k) == abs(best - k) && sum < best))
                best = sum;
            if (sum < k)
                l++;
            else
                r--;
        }
    }
    printf("%d\n", best);
    return 0;
}

