#include <string.h>

typedef struct Node {
    int v;
    struct Node *next;
} Node;
void clear(Node *h) {
    while (h) {
        Node *n = h->next;
        free(h);
        h = n;
    }
}
int main(void) {
    int n, k;
    scanf("%d%d", &n, &k);
    Node *head = NULL, **tail = &head;
    for (int i = 0; i < n; i++) {
        Node *p = malloc(sizeof *p);
        if (!p) {
            clear(head);
            return 1;
        }
        scanf("%d", &p->v);
        p->next = NULL;
        *tail = p;
        tail = &p->next;
    }
    Node dummy = {0, head};
    Node *before = &dummy;
    while (1) {
        Node *end = before;
        for (int i = 0; i < k && end; i++)
            end = end->next;
        if (!end)
            break;
        Node *after = end->next, *start = before->next, *prev = after, *cur = start;
        while (cur != after) {
            Node *next = cur->next;
            cur->next = prev;
            prev = cur;
            cur = next;
        }
        before->next = end;
        before = start;
    }
    head = dummy.next;
    if (!head)
        puts("EMPTY");
    for (Node *p = head; p; p = p->next)
        printf("%d%c", p->v, p->next ? ' ' : '\n');
    clear(head);
    return 0;
}

