#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int a, d, id;
} Task;
Task jobs[1000];
int heap[1000], hcount;
int cmp_arrival(const void *p, const void *q) {
    const Task *a = p, *b = q;
    return (a->a > b->a) - (a->a < b->a);
}
int less_job(int x, int y) {
    return jobs[x].d < jobs[y].d || (jobs[x].d == jobs[y].d && jobs[x].id < jobs[y].id);
}
void heap_push(int x) {
    int i = hcount++;
    while (i && less_job(x, heap[(i - 1) / 2])) {
        heap[i] = heap[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    heap[i] = x;
}
int heap_pop(void) {
    int result = heap[0], x = heap[--hcount], i = 0;
    while (2 * i + 1 < hcount) {
        int j = 2 * i + 1;
        if (j + 1 < hcount && less_job(heap[j + 1], heap[j]))
            j++;
        if (!less_job(heap[j], x))
            break;
        heap[i] = heap[j];
        i = j;
    }
    if (hcount)
        heap[i] = x;
    return result;
}
int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d%d", &jobs[i].a, &jobs[i].d);
        jobs[i].id = i;
    }
    qsort(jobs, (size_t)n, sizeof *jobs, cmp_arrival);
    long long time = 0, answer = 0;
    int next = 0;
    while (next < n || hcount) {
        if (!hcount && next < n && time < jobs[next].a)
            time = jobs[next].a;
        while (next < n && jobs[next].a <= time)
            heap_push(next++);
        int index = heap_pop();
        answer += time - jobs[index].a;
        time += jobs[index].d;
    }
    printf("%lld\n", answer);
    return 0;
}

