int parent[400], size[400], active[400];
int find_root(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
int main(void) {
    int r, c, q;
    scanf("%d%d%d", &r, &c, &q);
    for (int i = 0; i < r * c; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    int blocks = 0, dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    for (int i = 0; i < q; i++) {
        int x, y;
        scanf("%d%d", &x, &y);
        int id = x * c + y;
        if (!active[id]) {
            active[id] = 1;
            blocks++;
            for (int d = 0; d < 4; d++) {
                int nx = x + dr[d], ny = y + dc[d];
                if (nx >= 0 && nx < r && ny >= 0 && ny < c && active[nx * c + ny]) {
                    int a = find_root(id), b = find_root(nx * c + ny);
                    if (a != b) {
                        if (size[a] < size[b]) {
                            int t = a;
                            a = b;
                            b = t;
                        }
                        parent[b] = a;
                        size[a] += size[b];
                        blocks--;
                    }
                }
            }
        }
        printf("%s%d", i ? " " : "", blocks);
