#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int head[500], to[998], weight[998], next_edge[998], edge_count, up[10][500], depth[500];
long long distance_root[500];
void add_edge(int u, int v, int w) {
    to[edge_count] = v;
    weight[edge_count] = w;
    next_edge[edge_count] = head[u];
    head[u] = edge_count++;
}
int lca(int a, int b) {
    if (depth[a] < depth[b]) {
        int t = a;
        a = b;
        b = t;
    }
    int delta = depth[a] - depth[b];
    for (int k = 0; k < 10; k++)
        if (delta & (1 << k))
            a = up[k][a];
    if (a == b)
        return a;
    for (int k = 9; k >= 0; k--)
        if (up[k][a] != up[k][b]) {
            a = up[k][a];
            b = up[k][b];
        }
    return up[0][a];
}
int main(void) {
    int n, q;
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; i++)
        head[i] = -1;
    for (int i = 0; i < n - 1; i++) {
        int u, v, w;
        scanf("%d%d%d", &u, &v, &w);
        add_edge(u, v, w);
        add_edge(v, u, w);
    }
    int queue[500], front = 0, back = 0;
    queue[back++] = 0;
    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = next_edge[e]) {
            int v = to[e];
            if (v == up[0][u])
                continue;
            up[0][v] = u;
            depth[v] = depth[u] + 1;
            distance_root[v] = distance_root[u] + weight[e];
            for (int k = 1; k < 10; k++)
                up[k][v] = up[k - 1][up[k - 1][v]];
            queue[back++] = v;
        }
    }
    for (int i = 0; i < q; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        int ancestor = lca(a, b);
        printf("%lld\n", distance_root[a] + distance_root[b] - 2 * distance_root[ancestor]);
    }
    if (!q)
        puts("EMPTY");
    return 0;
}

