    for (int i = 0; i < n; i++)
        for (int s = target; s >= a[i]; s--)
            if (reachable[s - a[i]])
                reachable[s] = 1;
    int best = target;
    while (!reachable[best])
        best--;
    printf("%d\n", total - 2 * best);
    return 0;
}

